def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 200 or not isinstance(responseBody, dict) or responseBody.get("code") != 0:
        raise Blocked("社区准备请求失败")
    data = responseBody.get("data")
    if not isinstance(data, list) or len(data) < 2:
        raise Blocked("不足两个可用社区，公开 HTTP 没有创建接口")
    if not data[0].get("id") or not data[1].get("id") or data[0]["id"] == data[1]["id"]:
        raise Blocked("前两项社区ID缺失或不独立，无法绑定双社区准备")
    return True

def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 200 or not isinstance(responseBody, dict) or responseBody.get("code") != 0:
        raise Blocked("注册准备失败；不能删除来源不明的已有身份")
    data = responseBody["data"]
    if not data.get("user", {}).get("id") or not data.get("accessToken") or not data.get("refreshToken"):
        raise Blocked("注册响应缺少用户ID或清理凭证；已提取值仍进入finally")
    assert data["user"]["communityId"] == globalParam["COMMUNITY_A"]
    return True

