def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 200 or responseBody.get("code") != 0:
        raise Blocked("读取注册用户初始社区时间失败")
    assert responseBody["data"]["id"] == globalParam["USER_A"]
    assert responseBody["data"]["communityId"] == globalParam["COMMUNITY_A"]
    changed = responseBody["data"].get("communityChangedAt")
    if not isinstance(changed, str) or not changed:
        raise Blocked("communityChangedAt 为空或非字符串")
    return True

def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 200 or responseBody.get("code") != 0:
        raise Blocked("七天自然等待后刷新失败，不能继续使用过期访问令牌；仍需清理账号")
    assert responseBody["data"]["user"]["id"] == globalParam["USER_A"]
    assert responseBody["data"]["accessToken"] and responseBody["data"]["refreshToken"]
    return True

